window.FILM_WORK_PROMPTS={"work_id":"src-4a5f073350e67f64","records":[{"work_id":"src-4a5f073350e67f64","frame_id":"WC-14a8345bd7defd52","source_url":"https://upload.wikimedia.org/wikipedia/commons/7/74/Arch_of_ostrich_feathers_in_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","source_page":"https://commons.wikimedia.org/wiki/File:Arch_of_ostrich_feathers_in_Cleopatra.jpg","scene":"埃及艳后庞大的皇家游船甲板上，两排侍从高举巨大的白色鸵鸟羽扇，在幽暗舱厅中央搭起一道层叠璀璨的白色羽拱门。","analysis":"奥斯卡最佳摄影得主维克多·米尔纳在此展现了塞西尔·B·戴米尔史诗巨制最具标志性的纵深奇观构图：高反差顶光精准投射在中心对称排列的数十把巨型白色鸵鸟羽扇上，使其在幽暗深邃的船舱背景中如发光的贝壳般层层绽放，前景趴伏的侍女与波光粼粼的地面倒影进一步强化了奢华神秘的宫廷仪式感。","prompt":"1934年塞西尔·B·戴米尔执导、维克多·米尔纳奥斯卡最佳摄影获奖电影《埃及艳后》经典黑白大远景剧照，1.37:1画幅。奢华恢弘的古埃及皇家游船大殿内，采用严格的中心对称透视构图，两侧侍从高举巨大的白色鸵鸟毛羽扇，在画面中央交汇成一道层层叠叠、潔白耀眼的拱形羽廊。前景昏暗的甲板上躺卧着身姿曼妙的宫廷舞女，背景两侧是装饰华丽的船舱立柱与光影斑驳的帷幕，明暗反差极具戏剧张力，好莱坞黄金时代35毫米黑白胶片画质。","verification":"观图待人工核","selection":"全网检索公有领域与权威剧照档案精选","model":"全网检索与剧照观图编写","created":"2026-10-20T09:40:10+08:00","analysis_kind":"全网检索与剧照观图编写","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://upload.wikimedia.org/wikipedia/commons/7/74/Arch_of_ostrich_feathers_in_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","observed_dimensions":[1007,756],"source_thumbnail_dimensions":[1007,756],"source_image_match_mae":0.0,"observed_resolution":"normal","observation_limits":[],"id":"VP-2980bbc38bed3138","origin":"visual"},{"work_id":"src-4a5f073350e67f64","frame_id":"WC-d830052e830df3ad","source_url":"https://upload.wikimedia.org/wikipedia/commons/9/96/Cleopatra_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","source_page":"https://commons.wikimedia.org/wiki/File:Cleopatra_3.jpg","scene":"古典宫殿立柱前，身穿装饰艺术风格金属镂空礼服的克娄巴特拉（克劳黛·考尔白饰）侧身回眸，露出迷人微笑。","analysis":"米尔纳运用好莱坞黄金时代最考究的柔焦肖像布光（Glamour Lighting）：柔和的主光从左上方照亮考尔白齐刘海下的弯眉、明亮双眸与娇艳微笑，同时在她古铜质感的金属胸衣与圆润肩头上打出丝绸般的高光过渡，背景竖向排列的浅浮雕石柱在柔焦中衬托出女王的艳丽与威仪。","prompt":"1934年奥斯卡最佳摄影获奖电影《埃及艳后》黑白中近景肖像剧照。克劳黛·考尔白饰演的埃及艳后克娄巴特拉侧身站在古埃及宫殿内，她留着标志性的乌黑齐刘海与及肩直发，佩戴精致的金属额饰，身穿带有装饰艺术（Art Deco）几何美感的深色金属光泽挂脖露肩礼服。柔美的主光勾勒出她精致的五官与迷人微笑，背景是虚化的古埃及竖向石柱与浅灰墙面，光影细腻柔润，1930年代派拉蒙黑白胶片质感。","verification":"观图待人工核","selection":"全网检索公有领域与权威剧照档案精选","model":"全网检索与剧照观图编写","created":"2026-10-20T09:40:12+08:00","analysis_kind":"全网检索与剧照观图编写","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://upload.wikimedia.org/wikipedia/commons/9/96/Cleopatra_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","observed_dimensions":[1007,767],"source_thumbnail_dimensions":[1007,767],"source_image_match_mae":0.0,"observed_resolution":"normal","observation_limits":[],"id":"VP-d2728f360c123df4","origin":"visual"},{"work_id":"src-4a5f073350e67f64","frame_id":"WC-8effd060fb76d584","source_url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Closeup_of_Claudette_Colbert_as_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","source_page":"https://commons.wikimedia.org/wiki/File:Closeup_of_Claudette_Colbert_as_Cleopatra.jpg","scene":"深邃幽暗的暗调背景中，克娄巴特拉（克劳黛·考尔白饰）从浓密刘海下直视镜头，面庞在蝶形顶光下显得神秘而冷艳。","analysis":"这一特写镜头堪称1930年代派拉蒙低压暗调（Low-key）明星肖像摄影的典范：米尔纳将背景与服饰完全压入深沉的丝绒黑影之中，仅以一束精确聚拢的顶前蝶形光（Butterfly Light）照亮考尔白的双眼、鼻梁与饱满双唇，发丝边缘泛起微弱轮廓光，完美传递出政治博弈中埃及女王的深不可测。","prompt":"1934年电影《埃及艳后》黑白面部特写静帧，维克多·米尔纳暗调肖像摄影。几乎全黑的深邃背景中，克劳黛·考尔白饰演的克娄巴特拉正面凝视镜头，乌黑的齐刘海与微卷发丝框住她精致的鹅蛋脸，柳叶细眉微挑，深邃的大眼睛闪烁着冷静而诱惑的光芒。柔和而集中的顶前主光精准照亮她的面庞中心，鼻下投出浅浅的蝶形阴影，四周隐没于浓郁夜色，极富戏剧感染力的35毫米黑白胶片特写。","verification":"观图待人工核","selection":"全网检索公有领域与权威剧照档案精选","model":"全网检索与剧照观图编写","created":"2026-10-20T09:40:14+08:00","analysis_kind":"全网检索与剧照观图编写","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Closeup_of_Claudette_Colbert_as_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","observed_dimensions":[996,768],"source_thumbnail_dimensions":[996,768],"source_image_match_mae":0.0,"observed_resolution":"normal","observation_limits":[],"id":"VP-20e6fac963d8aad7","origin":"visual"},{"work_id":"src-4a5f073350e67f64","frame_id":"WC-315c764b1b5fe21c","source_url":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Henry_Wilcoxon_as_Marc_Antony.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","source_page":"https://commons.wikimedia.org/wiki/File:Henry_Wilcoxon_as_Marc_Antony.jpg","scene":"古罗马军帐与石柱背景前，身穿金属铠甲与深色披风的马克·安东尼（亨利·威尔考克森饰）斜倚榻上，目光冷峻地注视前方。","analysis":"针对男性统帅角色，米尔纳改用硬朗的高反差侧光（ Chiaroscuro Side Lighting）：强烈的左侧主光如刀刻般塑造出威尔考克森深陷的眼窝、紧抿的嘴角与粗壮的右臂肌肉，金属护肩上的狮头浮雕闪烁冷冽高光，与右侧沉入阴影的披风形成鲜明力量感对比。","prompt":"1934年电影《埃及艳后》黑白中景剧照，维克多·米尔纳摄影。亨利·威尔考克森饰演的罗马统帅马克·安东尼半躺在古典石柱殿堂的软榻上，他留着浓密微卷的短发，身穿镶嵌浮雕纹饰的古罗马金属胸甲与臂甲，肩披厚重的深色斗篷，健硕的右臂支在榻沿。硬朗的左侧高反差主光照亮他刚毅冷峻的脸庞与金属甲胄高光，背景可见古典白色圆柱与侍立人影，经典35毫米黑白胶片质感。","verification":"观图待人工核","selection":"全网检索公有领域与权威剧照档案精选","model":"全网检索与剧照观图编写","created":"2026-10-20T09:40:16+08:00","analysis_kind":"全网检索与剧照观图编写","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Henry_Wilcoxon_as_Marc_Antony.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","observed_dimensions":[1007,767],"source_thumbnail_dimensions":[1007,767],"source_image_match_mae":0.0,"observed_resolution":"normal","observation_limits":[],"id":"VP-107a6adf5f885a12","origin":"visual"},{"work_id":"src-4a5f073350e67f64","frame_id":"WC-87de46c4a3da56ea","source_url":"https://upload.wikimedia.org/wikipedia/commons/0/07/Julius_Caesar_and_Cleopatra_in_Cecil_B._DeMille%27s_1934_film_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","source_page":"https://commons.wikimedia.org/wiki/File:Julius_Caesar_and_Cleopatra_in_Cecil_B._DeMille's_1934_film_Cleopatra.jpg","scene":"宏伟的古埃及托勒密王宫大殿内，克娄巴特拉斜倚在左侧华贵软榻上，右侧身披深色托加长袍的尤利乌斯·凯撒（沃伦·威廉饰）手持卷轴伫立对峙，四周卫兵林立。","analysis":"米尔纳在此运用广角大景深镜头统摄戴米尔标志性的巨型宫廷布景：画面左侧斜卧的女王与右侧挺立的凯撒形成一低一高、一柔一刚的戏剧对峙，中景与远景处手持长矛盾牌的罗马军团士兵、埃及祭司与高耸入云的纸莎草柱列层次分明，展现了无与伦比的古典好莱坞场面调度功力。","prompt":"1934年奥斯卡最佳摄影获奖电影《埃及艳后》黑白全景剧照，1.37:1画幅。氣势恢宏的亚历山大王宫大殿内，巨大的古埃及莲花柱与浮雕壁画耸立在背景中。画面左侧，克娄巴特拉（克劳黛·考尔白饰）身穿浅色华服斜倚在铺满兽皮与丝绸的雕花软榻上；画面右侧，尤利乌斯·凯撒（沃伦·威廉饰）身披深色古罗马长袍、手持莎草纸卷轴威严站立。大殿后方整齐排列着持矛握盾的卫兵与宫廷侍从，大景深黑白光影层次丰富。","verification":"观图待人工核","selection":"全网检索公有领域与权威剧照档案精选","model":"全网检索与剧照观图编写","created":"2026-10-20T09:40:18+08:00","analysis_kind":"全网检索与剧照观图编写","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://upload.wikimedia.org/wikipedia/commons/0/07/Julius_Caesar_and_Cleopatra_in_Cecil_B._DeMille%27s_1934_film_Cleopatra.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","observed_dimensions":[1008,767],"source_thumbnail_dimensions":[1008,767],"source_image_match_mae":0.0,"observed_resolution":"normal","observation_limits":[],"id":"VP-752d2b55379843e6","origin":"visual"}]};